insert into faith_source_nodes (sigil_source_row_id, tier, node_index, options)
select staged.id, parsed.tier, parsed.node_index, parsed.options
from parsed
join staged on staged.external_key = parsed.external_key
on conflict (sigil_source_row_id) do update
set tier = excluded.tier, node_index = excluded.node_index, options = excluded.options;

with staged as (
  select sigil_source_rows.id, source_records.external_key
  from sigil_source_rows
  join source_records on source_records.id = sigil_source_rows.source_record_id
  where source_records.entity_type = 'sigil_source_row'
),
parsed (external_key, rule_kind, label, rule_values) as (
  values
    ('workbook:Archero Sigils.xlsx:sheet:Faith:row:3', 'point_cost', 'Unlock', '{"Rare Sigil": "50pt", "Epic Sigil": "150pt", "Legendary Sigil": "250pt", "Arcana Sigil": "500pt"}'::jsonb),
    ('workbook:Archero Sigils.xlsx:sheet:Faith:row:4', 'point_cost', 'Enhance', '{"Rare Sigil": "5pt", "Epic Sigil": "7pt", "Legendary Sigil": "10pt", "Arcana Sigil": "15pt"}'::jsonb),
    ('workbook:Archero Sigils.xlsx:sheet:Faith:row:5', 'point_cost', 'Advance', '{"Rare Sigil": "20pt", "Epic Sigil": "30pt", "Legendary Sigil": "50pt", "Arcana Sigil": "75pt"}'::jsonb),
    ('workbook:Archero Sigils.xlsx:sheet:Faith:row:6', 'point_cost', 'Evolve', '{"Rare Sigil": "50pt", "Epic Sigil": "70pt", "Legendary Sigil": "150pt", "Arcana Sigil": "200pt"}'::jsonb),
    ('workbook:Archero Sigils.xlsx:sheet:Faith:row:9', 'blessing_points', 'Stat Blessing', '{"note": "Faith Blessing Points X1"}'::jsonb),
    ('workbook:Archero Sigils.xlsx:sheet:Faith:row:10', 'blessing_points', 'Potent Stat Blessing', '{"note": "Faith Blessing Points X1"}'::jsonb),
    ('workbook:Archero Sigils.xlsx:sheet:Faith:row:11', 'blessing_points', 'Battle Skill Blessing', '{"note": "Faith Blessing Points X1"}'::jsonb),
    ('workbook:Archero Sigils.xlsx:sheet:Faith:row:12', 'blessing_points', 'Core Blessing', '{"note": "Faith Blessing Points X2"}'::jsonb)
)
insert into faith_source_rules (sigil_source_row_id, rule_kind, label, rule_values)
select staged.id, parsed.rule_kind, parsed.label, parsed.rule_values
from parsed
join staged on staged.external_key = parsed.external_key
on conflict (sigil_source_row_id) do update
set rule_kind = excluded.rule_kind, label = excluded.label, rule_values = excluded.rule_values;
